static const Display_LvglFontGlyphDsc_t *Display_LvglFontFindGlyph(uint32_t letter)
{
  uint32_t left = 0U;
  uint32_t right = (uint32_t)(sizeof(s_zh_glyphs) / sizeof(s_zh_glyphs[0]));

  while (left < right) {
    uint32_t mid = left + ((right - left) / 2U);
    if (s_zh_glyphs[mid].codepoint == letter) {
      return &s_zh_glyphs[mid];
    }
    if (s_zh_glyphs[mid].codepoint < letter) {
      left = mid + 1U;
    } else {
      right = mid;
    }
  }

  return NULL;
}

static bool Display_LvglFontGetGlyphDsc(const lv_font_t *font, lv_font_glyph_dsc_t *dsc_out, uint32_t letter, uint32_t letter_next)
{
  const Display_LvglFontGlyphDsc_t *glyph;

  (void)font;
  (void)letter_next;
  glyph = Display_LvglFontFindGlyph(letter);
  if (glyph == NULL) {
    return false;
  }

  dsc_out->adv_w = glyph->adv_w;
  dsc_out->box_w = glyph->box_w;
  dsc_out->box_h = glyph->box_h;
  dsc_out->ofs_x = glyph->ofs_x;
  dsc_out->ofs_y = glyph->ofs_y;
  dsc_out->bpp = 4;
  dsc_out->is_placeholder = 0;
  return true;
}

static const uint8_t *Display_LvglFontGetGlyphBitmap(const lv_font_t *font, uint32_t letter)
{
  const Display_LvglFontGlyphDsc_t *glyph;

  (void)font;
  glyph = Display_LvglFontFindGlyph(letter);
  if (glyph == NULL) {
    return NULL;
  }
  return &s_zh_bitmap[glyph->bitmap_index];
}

